package net.minecraft.world;import java.util.*;import net.minecraft.block.Block;import net.minecraft.tileentity.TileEntity; public class World{public boolean isRemote;private final Map<String,Block> blocks=new HashMap<>();private final Map<String,TileEntity> tiles=new HashMap<>();private String key(int x,int y,int z){return x+","+y+","+z;}public Block getBlock(int x,int y,int z){return blocks.getOrDefault(key(x,y,z),Block.AIR);}public TileEntity getTileEntity(int x,int y,int z){return tiles.get(key(x,y,z));}public void setTileEntity(int x,int y,int z,TileEntity tile){tiles.put(key(x,y,z),tile);tile.worldObj=this;tile.xCoord=x;tile.yCoord=y;tile.zCoord=z;}public boolean setBlock(int x,int y,int z,Block block){blocks.put(key(x,y,z),block);return true;}public boolean setBlockToAir(int x,int y,int z){blocks.remove(key(x,y,z));tiles.remove(key(x,y,z));return true;}public void removeTileEntity(int x,int y,int z){tiles.remove(key(x,y,z));}}
